<?php
namespace ScratchByPHP\Debug;
final class DebugCollector { private bool $enabled=false; private array $events=[]; public function enable():self{$this->enabled=true;return $this;} public function disable():self{$this->enabled=false;return $this;} public function enabled():bool{return $this->enabled;} public function record(string $type,array $data=[]):void{if(!$this->enabled)return;$this->events[]=['time'=>microtime(true),'type'=>$type,'data'=>$this->redact($data)];} private function redact(mixed $v,?string $k=null):mixed{if(is_array($v)){foreach($v as $key=>$val)$v[$key]=$this->redact($val,(string)$key);return $v;}if($k&&preg_match('/password|token|cookie|session|authorization|csrf/i',$k))return '[REDACTED]';return $v;} public function events():array{return $this->events;} public function requests():array{return array_values(array_filter($this->events,fn($e)=>$e['type']==='http'));} public function clear():self{$this->events=[];return $this;} }
